input.command:
$path = "D:\timzhao\Downloads\PHD_FABLE5_FINAL_RESTART_PS51_FIXED_2026-07-24\01_PhD_Research\06_PhD_Strategy_and_HSX_Publication_2026-07\evidence\10A_GAN_WBG_SOURCES.csv"
$csv = Import-Csv -Path $path
Write-Output "Row count: $($csv.Count)"
Write-Output "Column count: $($csv[0].PSObject.Properties.Name.Count)"
Write-Output "Columns: $($csv[0].PSObject.Properties.Name -join ', ')"
$ids = $csv | Select-Object -ExpandProperty source_id
$dupIds = $ids | Group-Object | Where-Object {$_.Count -gt 1}
Write-Output "Duplicate source_ids: $($dupIds.Count)"
$dois = $csv | Select-Object -ExpandProperty doi
$dupDois = $dois | Group-Object | Where-Object {$_.Count -gt 1}
Write-Output "Duplicate DOIs: $($dupDois.Count)"
if ($dupDois.Count -gt 0) { $dupDois | ForEach-Object { Write-Output "  DUP DOI: $($_.Name) x$($_.Count)" } }
$badPeer = $csv | Where-Object { $_.peer_review_status -ne 'verified_peer_reviewed' }
Write-Output "Rows with non-verified peer_review_status: $($badPeer.Count)"
$badAccess = $csv | Where-Object { $_.access_level -notin @('full_text','abstract_metadata','metadata_only') }
Write-Output "Rows with invalid access_level: $($badAccess.Count)"
$badTier = $csv | Where-Object { $_.quality_tier -notin @('A','B','C') }
Write-Output "Rows with invalid quality_tier: $($badTier.Count)"
$emptyFields = $csv | Where-Object { [string]::IsNullOrWhiteSpace($_.doi) -or [string]::IsNullOrWhiteSpace($_.title) -or [string]::IsNullOrWhiteSpace($_.claims_supported) }
Write-Output "Rows with empty doi/title/claims_supported: $($emptyFields.Count)"

$path = "D:\timzhao\Downloads\PHD_FABLE5_FINAL_RESTART_PS51_FIXED_2026-07-24\01_PhD_Research\06_PhD_Strategy_and_HSX_Publication_2026-07\evidence\10A_GAN_WBG_SOURCES.csv"
$csv = Import-Csv -Path $path
Write-Output "--- Venue distribution ---"
$csv | Group-Object venue | Sort-Object Count -Descending | ForEach-Object { Write-Output "$($_.Count)  $($_.Name)" }
Write-Output "--- Year distribution ---"
$csv | Group-Object year | Sort-Object Name | ForEach-Object { Write-Output "$($_.Name): $($_.Count)" }
Write-Output "--- Quality tier distribution ---"
$csv | Group-Object quality_tier | Sort-Object Name | ForEach-Object { Write-Output "$($_.Name): $($_.Count)" }
Write-Output "--- source_type distribution ---"
$csv | Group-Object source_type | ForEach-Object { Write-Output "$($_.Name): $($_.Count)" }
Write-Output "--- access_level distribution ---"
$csv | Group-Object access_level | ForEach-Object { Write-Output "$($_.Name): $($_.Count)" }
